// Thinking Process:
// 1. Create a reproduction script that has a Form parameter before a File parameter.
// 2. Run it using TestClient and check for 422.

python3 - <<'EOF'
from fastapi import FastAPI, File, Form
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

@app.post("/upload")
async def upload(name: Annotated[str, Form()], file: Annotated[bytes, File()]):
    return {"name": name, "file_size": len(file)}

client = TestClient(app)

def test_form_before_file():
    # Sending a multipart form request
    files = {"file": ("test.txt", b"hello world")}
    data = {"name": "test_name"}
    response = client.post("/upload", data=data, files=files)
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_before_file()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
EOF

